// The media naming and winner rules on real files anyone can read:
// testdata/media-synth (generated by scripts/gen-media-synth.sh) is cataloged
// with the pure-Go extractors and planned. Every line is one rule: a changed
// line is a change of the frozen media contract, not a test to update.
func TestMediaSynthRegression(t *testing.T) {
	t.Setenv("ONEFOLD_NO_EXTERNAL", "1") // public CI has no ffprobe/exiftool: same records everywhere
	prev := meta.Zone()
	meta.SetZone(time.UTC) // video times come in UTC, file times are instants
	defer meta.SetZone(prev)

	// a scratch copy with fixed file times: the files without a capture time
	// fall back to their mtime, which a checkout does not keep
	root := t.TempDir()
	mtime := time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC)
	src := filepath.Join("..", "..", "testdata", "media-synth")
	err := filepath.WalkDir(src, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		dst := filepath.Join(root, rel)
		if d.IsDir() {
			return os.MkdirAll(dst, 0o755)
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		if err := os.WriteFile(dst, b, 0o644); err != nil {
			return err
		}
		return os.Chtimes(dst, mtime, mtime)
	})
	if err != nil {
		t.Fatal(err)
	}
	exts, _, err := kinds.PresetExts([]string{"media"})
	if err != nil {
		t.Fatal(err)
	}
	recs, _, err := catalog.Collect([]string{filepath.Join(root, "A"), filepath.Join(root, "B")},
		catalog.Options{Workers: 2, Exts: exts, Host: "synth"})
	if err != nil {
		t.Fatal(err)
	}
	rel := func(p string) string {
		r, _ := filepath.Rel(root, p)
		return filepath.ToSlash(r)
	}
	var got []string
	for _, a := range BuildActionsWith(Plan(recs), Options{}) {
		var drops []string
		for _, d := range a.Drops {
			drops = append(drops, rel(d.Path)+" "+d.Reason)
		}
		sort.Strings(drops)
		got = append(got, strings.TrimSpace(rel(a.SrcPath)+" -> "+a.CanonRel+" "+strings.Join(drops, ", ")))
	}
	sort.Strings(got)
	want := []string{
		// one shot in two formats (same sub-second): one asset per format
		"A/DSC_0005.jpg -> PICTURES/JPG/2022/DSC_20220102_030406.jpg",
		"A/DSC_0005.tif -> PICTURES/TIFF/2022/DSC_20220102_030406.tif",
		// no sub-second: identity is the bytes; the exact copy is dropped
		"A/IMG_0001.jpg -> PICTURES/JPG/2021/IMG_20210506_070809.jpg B/IMG_0001 (1).jpg exact-dupe",
		// burst: two sub-seconds of one second, two assets, collision suffix
		"A/IMG_0003.jpg -> PICTURES/JPG/2022/DSC_20220102_030405.jpg",
		"A/IMG_0004.jpg -> PICTURES/JPG/2022/DSC_20220102_030405_01.jpg",
		// one sub-second shot: the largest resolution wins
		"A/IMG_0010.jpg -> PICTURES/JPG/2021/IMG_20210607_101112.jpg B/IMG_0010_small.jpg lower-res",
		// an edit is its own asset with its own prefix
		"A/IMG_0010_edit.jpg -> PICTURES/JPG/2021/SNPSD_20210607_101112.jpg",
		// equal resolution: the HDR output wins
		"A/IMG_0011_HDR.jpg -> PICTURES/JPG/2021/IMG_20210607_101113.jpg B/IMG_0011.jpg variant",
		// equal resolution, no HDR: the larger file wins
		"A/IMG_0012.jpg -> PICTURES/JPG/2021/IMG_20210607_101114.jpg B/IMG_0012.jpg smaller",
		// same start and length: the higher resolution wins
		"A/VID_0001.mp4 -> VIDEOS/2023/VID_20230708_091009.mp4 B/VID_0001_lq.mp4 lower-res",
		"A/VID_0003.mp4 -> VIDEOS/2024/VID_20240203_040505.mp4",
		// same bytes as .png and as .jpg: two assets (one per format)
		"A/logo.png -> PICTURES/PNG/2020/IMG_20200101_000000.png",
		// another device in the same sub-second: its own asset
		"B/DSC_0010.jpg -> PICTURES/JPG/2021/DSC_20210607_101112.jpg",
		// no sub-second: a lower resolution is distinct content, kept
		"B/IMG_0001_small.jpg -> PICTURES/JPG/2021/IMG_20210506_070809_02.jpg",
		// time from the file name
		"B/IMG_20190102_030405.jpg -> PICTURES/JPG/2019/IMG_20190102_030405.jpg",
		// another phone in the same second: same name, collision suffix
		"B/IMG_9001.jpg -> PICTURES/JPG/2021/IMG_20210506_070809_01.jpg",
		// other length: its own asset
		"B/VID_0002.mp4 -> VIDEOS/2023/VID_20230708_091005.mp4",
		"B/logo.jpg -> PICTURES/JPG/2020/IMG_20200101_000000.jpg",
		// no capture time: the file time
		"B/undated.png -> PICTURES/PNG/2020/IMG_20200101_000000_01.png",
	}
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Errorf("media plan of testdata/media-synth changed:\ngot:\n%s\nwant:\n%s", strings.Join(got, "\n"), strings.Join(want, "\n"))
	} // the catalog workers emit records in any order: the media winners must
	// not depend on it
	rev := slices.Clone(recs)
	slices.Reverse(rev)
	if a, b := winners(Plan(recs)), winners(Plan(rev)); !slices.Equal(a, b) {
		t.Errorf("media winners depend on the record order:\n%s\nreversed:\n%s", strings.Join(a, "\n"), strings.Join(b, "\n"))
	}
}

// winners lists the media winners of a plan, sorted.
func winners(r *Result) []string {
	var out []string
	for _, a := range r.Golden {
		if k := a.Winner.Meta.Kind; k == "photo" || k == "video" {
			out = append(out, a.Winner.Path)
		}
	}
	sort.Strings(out)
	return out
}

// Options.SelfContained writes the winner's sub-second, duration and
// dimensions into each action; without it the action JSON has none of them
// (the historical bytes pinned by TestMediaPlanRegression).
func TestSelfContainedActions(t *testing.T) {
	recs := []catalog.Record{
		{Path: "/r/IMG_1.jpg", Hash: "p", Size: 10, Room: "/r", Host: "h",
			Meta: meta.Meta{Kind: "photo", Time: "2019-08-09 23:02:16", SubSecNs: 250000000, Prefix: "IMG", Width: 4000, Height: 3000}},
		{Path: "/r/VID_1.mp4", Hash: "v", Size: 20, Room: "/r", Host: "h",
			Meta: meta.Meta{Kind: "video", Time: "2019-08-09 23:02:16", Width: 1920, Height: 1080, DurationSec: 12.5}},
	}
	for _, sc := range []bool{false, true} {
		o := Options{SelfContained: sc}
		for _, a := range BuildActionsWith(PlanWith(append([]catalog.Record(nil), recs...), o), o) {
			b, _ := json.Marshal(&a)
			has := strings.Contains(string(b), `"width"`)
			if has != sc {
				t.Fatalf("self-contained=%v: %s", sc, b)
			}
			if !sc {
				continue
			}
			switch a.Kind {
			case "photo":
				if a.SubSecNs != 250000000 || a.Width != 4000 || a.Height != 3000 || a.DurationSec != 0 {
					t.Errorf("photo %+v", a)
				}
			case "video":
				if a.DurationSec != 12.5 || a.Width != 1920 || a.Height != 1080 || strings.Contains(string(b), "subSecNs") {
					t.Errorf("video %s", b)
				}
			}
		}
	}
}

// VideoTolerance: a re-encoded copy whose duration crossed a rounding edge
// joins its original (lower-res drop); off, it stays a separate asset as the
// frozen rule says; a clip of another length stays apart either way.
func TestVideoTolerance(t *testing.T) {
	v := func(p, h string, w, ht int, d float64) catalog.Record {
		return catalog.Record{Path: p, Hash: h, Size: int64(w), Room: "/r", Host: "h",
			Meta: meta.Meta{Kind: "video", Time: "2023-07-08 09:10:11", Width: w, Height: ht, DurationSec: d, Prefix: "VID"}}
	}
	recs := []catalog.Record{v("/r/hq.mp4", "a", 1920, 1080, 10.4), v("/r/lq.mp4", "b", 640, 360, 10.6), v("/r/other.mp4", "c", 1920, 1080, 30)}
	for _, c := range []struct {
		tol    float64
		assets int
	}{{0, 3}, {0.5, 2}, {0.1, 3}} {
		r := PlanWith(append([]catalog.Record(nil), recs...), Options{VideoTolerance: c.tol})
		if r.Assets != c.assets {
			t.Errorf("tolerance %v: %d assets, want %d", c.tol, r.Assets, c.assets)
		}
		if c.assets == 2 && r.LowerRes != 1 {
			t.Errorf("tolerance %v: lower-res %d, want 1", c.tol, r.LowerRes)
		}
	}
}

// FilenameSeq: photos dated by a file name without a time of day keep its
// counter; off, they collide on the default time and get _NN by hash order.
func TestFilenameSeq(t *testing.T) {
	wa := func(n, h string) catalog.Record {
		return catalog.Record{Path: "/r/IMG-20200101-" + n + ".jpg", Hash: h, Size: 1, Room: "/r", Host: "h",
			Meta: meta.Meta{Kind: "photo", Time: "2020-01-01 10:00:00", TimeSource: "filename", Prefix: "IMG"}}
	}
	recs := []catalog.Record{wa("WA0007", "b"), wa("WA0002", "a"), {Path: "/r/IMG_1.jpg", Hash: "c", Size: 1, Room: "/r", Host: "h",
		Meta: meta.Meta{Kind: "photo", Time: "2020-01-01 10:00:00", TimeSource: "metadata", Prefix: "IMG"}}}
	got := func(o Options) string {
		var l []string
		for _, a := range BuildActionsWith(PlanWith(append([]catalog.Record(nil), recs...), o), o) {
			l = append(l, filepath.Base(a.SrcPath)+">"+a.CanonName)
		}
		sort.Strings(l)
		return strings.Join(l, " ")
	}
	if g := got(Options{}); g != "IMG-20200101-WA0002.jpg>IMG_20200101_100000.jpg IMG-20200101-WA0007.jpg>IMG_20200101_100000_01.jpg IMG_1.jpg>IMG_20200101_100000_02.jpg" {
		t.Errorf("off: %s", g)
	}
	if g := got(Options{FilenameSeq: true}); g != "IMG-20200101-WA0002.jpg>IMG_20200101_100000_WA0002.jpg IMG-20200101-WA0007.jpg>IMG_20200101_100000_WA0007.jpg IMG_1.jpg>IMG_20200101_100000.jpg" {
		t.Errorf("on: %s", g)
	}
}
